    world[TOWN_BREACH_STATE] = {
      alarmActiveUntil: 0,
      bellRingerId: 0,
      sightedMonsterId: 0,
      sightedAtStep: -1,
    };
  }
  return world[TOWN_BREACH_STATE];
}

function currentThreatMemory(world) {
  for (const [id, memory] of world.query(ThreatMemory)) {
